R(23,"reescrita",2,"'A fim de' pode ser substituída por 'para' em 'Votou-se rápido a fim de evitar atrasos'.","'A fim de' pode ser substituída por 'porque' em 'Votou-se rápido a fim de evitar atrasos'.","A fim de = para (finalidade).","troca finalidade por causa")
R(23,"reescrita",3,"'Haja vista' equivale a 'tendo em vista' em 'O pedido foi negado, haja vista a ausência de provas'.","'Haja vista' equivale a 'apesar de' em 'O pedido foi negado, haja vista a ausência de provas'.","Haja vista = tendo em vista.","troca causa por concessão")
R(23,"reescrita",3,"'Não obstante' pode ser substituída por 'apesar de' em 'Não obstante o recurso, a sentença foi mantida'.","'Não obstante' pode ser substituída por 'em razão de' em 'Não obstante o recurso, a sentença foi mantida'.","Não obstante = apesar de.","troca concessão por causa")
R(23,"reescrita",3,"'Tampouco' equivale a 'também não' em 'Não votou, tampouco opinou'.","'Tampouco' equivale a 'além disso' em 'Não votou, tampouco opinou'.","Tampouco = também não.","troca negação por adição")
R(23,"norma_culta",4,"Em 'Não fez outra coisa senão reclamar', 'senão' equivale a 'exceto'.","Em 'Não fez outra coisa senão reclamar', 'senão' deve ser grafado 'se não'.","Senão = exceto/a não ser.","confunde senão e se não")
R(23,"reescrita",3,"'A despeito de' tem valor concessivo e equivale a 'apesar de'.","'A despeito de' tem valor causal e equivale a 'por causa de'.","A despeito de = apesar de.","troca concessão por causa")
R(23,"reescrita",3,"'Porquanto' equivale a 'pois' ou 'porque', introduzindo explicação ou causa.","'Porquanto' equivale a 'embora', introduzindo concessão.","Porquanto = porque.","troca causa por concessão")
R(23,"reescrita",2,"'Bem como' tem valor aditivo e equivale a 'e também'.","'Bem como' tem valor adversativo e equivale a 'mas'.","Bem como = e também.","troca adição por oposição")
R(23,"reescrita",3,"Em 'Ele vota a favor, ao passo que ela se opõe', a locução 'ao passo que' exprime oposição.","Em 'Ele vota a favor, ao passo que ela se opõe', a locução 'ao passo que' exprime causa.","Ao passo que = oposição/proporção.","troca oposição por causa")
